import React, { useState } from 'react';

const TECH_CATEGORIES = [
  { id: 'frontend', label: 'Frontend Engineering', skills: [
    { name: 'Vue.js', icon: 'https://7span-website.b-cdn.net/a64cdd9d-1f07-4c53-8082-8b5bc9f45d94.svg' },
    { name: 'React', icon: 'https://7span-website.b-cdn.net/d9978c59-be76-4536-8bf0-fb25afff186a.svg' },
    { name: 'JavaScript', icon: 'https://7span-website.b-cdn.net/2c27e284-c9f0-4701-839f-f944485918a5.svg' },
    { name: 'TypeScript', icon: 'https://7span-website.b-cdn.net/6c9911ff-e402-4c36-a803-5ff286584cdd.svg' },
    { name: 'Nuxt.js', icon: 'https://7span-website.b-cdn.net/ccad2488-c500-4e7d-928f-3785279e3f48.svg' },
    { name: 'Next.js', icon: 'https://7span-website.b-cdn.net/b7499f79-10d3-4bce-8c8e-4cae3c3d15dc.svg' },
    { name: 'Tailwind CSS', icon: 'https://7span-website.b-cdn.net/c54f0931-db51-40c5-9862-1e2501ae50d1.svg' },
    { name: 'Vite', icon: 'https://7span-website.b-cdn.net/1a2ea041-e723-4e94-8c33-740e6b7c8531.svg' },
    { name: 'Bootstrap', icon: 'https://7span-website.b-cdn.net/8728b4da-dd9a-4e2f-aa59-a2803bb27f3d.svg' },
  ]},
  { id: 'backend', label: 'Backend Engineering', skills: [
    { name: 'Node.js', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/nodejs/nodejs-original.svg' },
    { name: 'Express', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/express/express-original.svg' },
    { name: 'Python', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/python/python-original.svg' },
    { name: 'MongoDB', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/mongodb/mongodb-original.svg' },
  ]},
  { id: 'mobile', label: 'Mobile Application Development', skills: [
    { name: 'React Native', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/react/react-original.svg' },
    { name: 'Flutter', icon: 'https://cdn.jsdelivr.net/gh/devicons/devicon/icons/flutter/flutter-original.svg' },
  ]},
  { id: 'design', label: 'Design', skills: [
    { name: 'Figma', icon: 'https://www.vectorlogo.zone/logos/figma/figma-icon.svg' },
    { name: 'Illustrator', icon: 'https://www.vectorlogo.zone/logos/adobe_illustrator/adobe_illustrator-icon.svg' },
  ]},
  { id: 'data', label: 'Data & Backend Platforms', skills: [] },
  { id: 'plugins', label: 'Plugins', skills: [] },
  { id: 'cms', label: 'CMS', skills: [] },
  { id: 'cloud', label: 'Cloud', skills: [] },
  { id: 'erp', label: 'ERP', skills: [] },
  { id: 'deployment', label: 'Deployment', skills: [] },
  { id: 'ecommerce', label: 'E-commerce', skills: [] },
  { id: 'qa', label: 'QA', skills: [] },
  { id: 'frameworks', label: 'Frameworks & Libraries', skills: [] },
  { id: 'nocode', label: 'No Code Apps', skills: [] },
];

export default function Technologies() {
  const [activeTab, setActiveTab] = useState('frontend');
  const activeCategory = TECH_CATEGORIES.find(cat => cat.id === activeTab) || TECH_CATEGORIES[0];

  return (
    <section className="py-section border-t border-black">
      <div className="container">
        <h2 className="font-display text-3xl md:text-4xl font-semibold lg:text-5xl uppercase">
          Technologies
        </h2>
        <p className="text-xl lg:text-2xl mt-2 text-gray-600">
          I help businesses design, build, and scale digital products with the right technology.
        </p>

        <div className="mt-8 flex flex-col lg:flex-row border border-black lg:h-[80vh]">
          {/* Sidebar */}
          <div className="lg:w-80 flex flex-col bg-gray-200 overflow-y-auto lg:scrollbar-left">
            {TECH_CATEGORIES.map((cat) => (
              <button
                key={cat.id}
                onClick={() => setActiveTab(cat.id)}
                className={`h-12 px-6 text-left transition-colors flex items-center relative ${
                  activeTab === cat.id ? 'bg-white text-black' : 'text-gray-500 hover:text-black border-r border-black'
                }`}
              >
                <div className="text-sm font-semibold font-mono uppercase leading-tight">
                  {cat.label}
                </div>
                {activeTab === cat.id && (
                  <div className="absolute right-0 top-0 bottom-0 w-[1px] bg-white z-10 hidden lg:block" />
                )}
              </button>
            ))}
            <div className="flex-1 border-r border-black" />
          </div>

          {/* Content Area */}
          <div className="flex-1 p-6 lg:p-12 overflow-y-auto bg-white">
            <div className="font-display text-3xl font-semibold lg:text-4xl mb-4">
              {activeCategory.label}
            </div>

            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 mt-4 border-l border-t border-black">
              {activeCategory.skills.map((skill) => (
                <div key={skill.name} className="border-r border-b border-black flex items-center flex-col p-6 group hover:bg-gray-50">
                  <div className="aspect-square size-12">
                    <img src={skill.icon} alt={skill.name} className="size-full object-contain grayscale group-hover:grayscale-0 transition-all duration-300" />
                  </div>
                  <div className="text-sm font-semibold font-mono uppercase leading-tight mt-3 text-center">
                    {skill.name}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
